mapper.update:
UPDATE stage_attempts sa
   SET heartbeat_at = CURRENT_TIMESTAMP,
       updated_at = CURRENT_TIMESTAMP
 WHERE sa.stage_name = 'RENDER_PROJECT_LOCAL'
   AND sa.status = 'RUNNING'
   AND sa.worker_id = #{workerId}
   AND sa.lease_token = #{leaseToken,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler}
   AND EXISTS (
     SELECT 1
       FROM generation_jobs gj
       JOIN project_render_input_snapshots pris ON pris.generation_job_id = gj.id
      WHERE gj.id = sa.generation_job_id
        AND gj.job_id = #{jobId,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler}
        AND pris.execution_target = 'LOCAL_DEVICE'
        AND pris.assigned_local_device_id = #{deviceId,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler}
   )

mapper.select:
SELECT EXISTS (
  SELECT 1
    FROM generation_jobs gj
    JOIN stage_attempts sa ON sa.generation_job_id = gj.id
    JOIN project_render_input_snapshots pris ON pris.generation_job_id = gj.id
   WHERE gj.job_id = #{jobId,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler}
     AND gj.status = 'RUNNING'
     AND sa.stage_name = 'RENDER_PROJECT_LOCAL'
     AND sa.status = 'RUNNING'
     AND sa.worker_id = #{workerId}
     AND sa.lease_token = #{leaseToken,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler}
     AND pris.execution_target = 'LOCAL_DEVICE'
     AND pris.assigned_local_device_id = #{deviceId,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler}
)
